package diag;
import static diag.Observe.*;
import java.io.*;import java.lang.instrument.*;import java.lang.reflect.*;import java.nio.file.*;import java.security.ProtectionDomain;import java.util.*;
import jdk.internal.org.objectweb.asm.*;import jdk.internal.org.objectweb.asm.commons.AdviceAdapter;
public final class C5Observe {
 static ThreadLocal<Object[]> active=new ThreadLocal<>();
 public static void premain(String path,Instrumentation inst)throws Exception{
  Observe.output=new PrintWriter(Files.newBufferedWriter(Path.of(path)));
  Runtime.getRuntime().addShutdownHook(new Thread(()->{synchronized(Observe.class){output.println("{\"event\":\"END\",\"rows\":"+rows+",\"errors\":"+errors+"}");output.close();}}));
  inst.addTransformer(new ClassFileTransformer(){public byte[] transform(ClassLoader cl,String cn,Class<?> r,ProtectionDomain pd,byte[] bytes){
   boolean ds=cn.equals("org/opentaint/dataflow/bidi/store/DemandStore"),limit=cn.equals("org/opentaint/dataflow/bidi/ap/LimitKt"),bs=cn.equals("org/opentaint/dataflow/bidi/engine/BlockRunState");
   if(!ds&&!limit&&!bs)return null;
   try{ClassReader cr=new ClassReader(bytes);ClassWriter cw=new ClassWriter(cr,ClassWriter.COMPUTE_MAXS);
    cr.accept(new ClassVisitor(Opcodes.ASM8,cw){public MethodVisitor visitMethod(int acc,String name,String desc,String sig,String[]ex){MethodVisitor mv=super.visitMethod(acc,name,desc,sig,ex);
     if(ds&&name.equals("offerDataPair"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){
      protected void onMethodEnter(){for(int i=0;i<7;i++)loadArg(i);visitMethodInsn(INVOKESTATIC,"diag/C5Observe","rowBegin","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}
      protected void onMethodExit(int op){visitMethodInsn(INVOKESTATIC,"diag/C5Observe","rowEnd","()V",false);}
     };
     if(limit&&name.equals("limitFacts"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadArg(0);loadArg(1);loadArg(2);visitMethodInsn(INVOKESTATIC,"diag/C5Observe","limit","(Ljava/lang/Object;Ljava/lang/Object;I)V",false);}};
     if(bs&&(acc&Opcodes.ACC_STATIC)==0&&name.startsWith("retainSummary"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);loadArg(1);visitMethodInsn(INVOKESTATIC,"diag/C5Observe","raw","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     if(bs&&name.equals("applyRecordView"))return new AdviceAdapter(Opcodes.ASM8,mv,acc,name,desc){protected void onMethodEnter(){loadThis();loadArg(0);loadArg(1);visitMethodInsn(INVOKESTATIC,"diag/C5Observe","view","(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V",false);}};
     return mv;
    }},ClassReader.EXPAND_FRAMES);System.err.println("C5_TRANSFORM "+cn);return cw.toByteArray();
   }catch(Throwable t){error("transform",t);return null;}
  }});
 }
 static boolean selected(int run,Object key){return run>=8&&run<=10&&String.valueOf(key).contains("BenchmarkTest01000$Test#doSomething");}
 static Object pattern(Object c)throws Exception{Class<?> p=Class.forName("org.opentaint.dataflow.bidi.ap.Pattern");return p.getConstructors()[0].newInstance(get(c,"fact"),get(c,"exclusion"));}
 public static void rowBegin(Object key,Object ops,Object member,Object raw,Object pair,Object policy,Object result){try{
  int run=((Number)get(policy,"run")).intValue();if(!selected(run,key))return;Object ap=get(ops,"manager");active.set(new Object[]{key,ap,member,raw,pair,policy,result});
  Object b=builder(ap,"C5_ROW",run,String.valueOf(key),"ROOT");call(b,"number","globalLimit",get(policy,"fieldLimit"));call(b,"premise","premise",member);call(b,"facts","raw",raw);call(b,"pattern","entry",get(pair,"entry"));call(b,"pattern","exit",get(pair,"exit"));emit(b);
 }catch(Throwable t){error("rowBegin",t);}}
 public static void rowEnd(){Object[] a=active.get();if(a==null)return;try{int run=((Number)get(a[5],"run")).intValue();int i=0;for(Object fact:(Collection<?>)call(a[6],"all")){Object b=builder(a[1],"C5_RESULTS",run,String.valueOf(a[0]),"ROOT");call(b,"premise","premise",a[2]);call(b,"facts","result",fact);call(b,"number","index",i++);emit(b);}}catch(Throwable t){error("rowEnd",t);}finally{active.remove();synchronized(Observe.class){output.flush();}}}
 public static void limit(Object ap,Object kept,int budget){Object[]a=active.get();if(a==null)return;try{int run=((Number)get(a[5],"run")).intValue();Object b=builder(ap,"C5_BEFORE_LIMIT",run,String.valueOf(a[0]),"ROOT");call(b,"number","budget",budget);call(b,"facts","kept",kept);call(b,"premise","premise",a[2]);call(b,"pattern","entry",get(a[4],"entry"));call(b,"pattern","exit",get(a[4],"exit"));emit(b);}catch(Throwable t){error("limit",t);}}
 public static void raw(Object core,Object premise,Object raw){try{int run=((Number)get(get(core,"config"),"index")).intValue();Object key=get(core,"key");if(!selected(run,key))return;Object b=builder(get(core,"ap"),"BEFORE_RETAIN",run,String.valueOf(key),String.valueOf(get(core,"scope")));call(b,"premise","premise",premise);call(b,"facts","raw",raw);emit(b);}catch(Throwable t){error("raw",t);}}
 public static void view(Object core,Object part,Object view){try{int run=((Number)get(get(core,"config"),"index")).intValue();Object key=get(core,"key");if(!selected(run,key))return;Object b=builder(get(core,"ap"),"SAVED_VIEW",run,String.valueOf(key),String.valueOf(get(core,"scope")));call(b,"facts","input",get(part,"added"));Object ref=get(part,"ref");call(b,"premise","premise",get(ref,"premise"));call(b,"text","call",String.valueOf(get(ref,"node")));call(b,"pattern","viewPremise",get(view,"premise"));call(b,"pattern","viewResult",pattern(get(view,"result")));call(b,"flag","demand",get(get(view,"result"),"demand"));emit(b);}catch(Throwable t){error("view",t);}}
}

